tool_input.new_string:
async function main() {
  assert.ok(fs.existsSync(REFERENCE), `missing Navbar reference fixture: ${REFERENCE}`)
  await verifyNginxSite()
  const browser = await chromium.launch({ headless: true })
  const failures = []
  try {
    const checks = [
      ['visual reference', () => verifyReference(browser)],
      ['overflow interactions', () => verifyOverflow(browser)],
      ['empty permissions', () => verifyEmptyPermissions(browser)]
    ]
    for (const [name, verify] of checks) {
      try {
        await verify()
      } catch (error) {
        failures.push({ name, error })
        console.error(`[navbar-visual] ${name} failed`, error.message)
      }
    }
  } finally {
    await browser.close()
  }
  if (failures.length) {
    const summary = failures.map(({ name, error }) => `${name}: ${error.message}`).join('\n')
    throw new Error(`navbar E2E verification failed:\n${summary}`)
  }
}
